{
  "families": [
    {
      "family": "pipelined",
      "ranges": [
        {"param": "data_width", "low": 13, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "budget_share": 0.7,
      "why": "Pipelined gives 1 result/cycle and the shortest combinational path per stage, so it has the best chance of reaching the 400 MSPS throughput constraint. The ranges cover the smallest data widths that can possibly meet 2^-12 accuracy (W>=13) and enough iterations/guards to find the minimal-LUT feasible designs."
    },
    {
      "family": "pipelined_m",
      "ranges": [
        {"param": "data_width", "low": 13, "high": 18, "choices": null},
        {"param": "n_iter", "low": 8, "high": 20, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]},
        {"param": "m", "low": 2, "high": 4, "choices": null}
      ],
      "budget_share": 0.3,
      "why": "Pipelined_m also gives 1 result/cycle but registers every m stages, which may reduce FF count and change the LUT/FF trade-off. We restrict m to 2..4 because larger m lengthens the combinational path and is less likely to meet 400 MSPS; this tests whether it can still be feasible while offering a different area point."
    }
  ],
  "rationale": "Only the pipelined families can plausibly meet the 400 MSPS single-lane throughput: iterative and unrolled_k need Fmax >= 400 * (cycles/result), which is well above 1 GHz for any allowed N and k. Accuracy requires max_abs_err <= 2^-12, so the output LSB must be at most 2^-11, implying data_width >= 13. The first round therefore searches pipelined and pipelined_m over data_width 13..18, n_iter 8..20, and the guard/rounding options to locate the minimal-LUT designs that satisfy both constraints and to start mapping the Pareto front. If no design meets the constraints, later rounds will confirm infeasibility."
}
